local config = {
  ui_story_31210401_1_dialog_content = "Kecuali beberapa lipatan lebih banyak di sana-sini, sampul kulit yang berat dan bersepuh ini tak ada bedanya dengan sebelumnya.",
  ui_story_31210401_2_dialog_content = "\"Lumopolis Temple Scriptures\"...",
  ui_story_31210401_3_dialog_content = "Nah, karena kurang lebih sudah membacanya, apa kamu ingat kisah yang kuceritakan dulu?",
  ui_story_31210401_4_dialog_content = "Kisah yang kamu ceritakan dulu...",
  ui_story_31210401_5_dialog_content = "Hei, Paloma!",
  ui_story_31210401_6_dialog_content = "Selamat siang. Kamu kemari untuk membaca, ya?",
  ui_story_31210401_7_dialog_content = "Selamat siang.",
  ui_story_31210401_8_dialog_content = "Buku yang kamu pegang... Itu \"Lumopolis Temple Scriptures\"?",
  ui_story_31210401_9_dialog_content = "Ya.",
  ui_story_31210401_10_dialog_content = "Aneh sekali. Kenapa tiba-tiba kamu ingin membaca buku seperti ini?",
  ui_story_31210401_11_dialog_content = "Ahaha... Aduh, aku jadi agak malu...",
  ui_story_31210401_12_dialog_content = "Ini karena aku belum pernah membaca buku tentang teologi atau agama sebelumnya.",
  ui_story_31210401_13_dialog_content = "Carleen yang merekomendasikan buku ini. Dia bilang, hampir semua orang di Lumopolis memilikinya.",
  ui_story_31210401_14_dialog_content = "Jadi, kupikir bagus kalau kugunakan buku ini sebagai perkenalan agama.",
  ui_story_31210401_15_dialog_content = "Oh, begitu.",
  ui_story_31210401_16_dialog_content = "Apa kamu benar-benar tahu isi buku ini, Caelestite?",
  ui_story_31210401_17_dialog_content = "Eh... Belum, sih.",
  ui_story_31210401_18_dialog_content = "Tapi, menurut tebakanku, ada legenda atau kisah yang menarik di dalamnya. Iya, 'kan?",
  ui_story_31210401_19_dialog_content = "Misalnya pertempuran di masa lampau tentang kebaikan dan kejahatan, 72 Lost Sons of Light...",
  ui_story_31210401_20_dialog_content = "... atau legenda Lumopolis di masa lalu dan God and Goddess of Light?",
  ui_story_31210401_21_dialog_content = "Lagi pula, ada banyak hal yang bisa ditawarkan Lumopolis. Jadi, mitos agamanya mungkin cukup rumit. Tebakanku benar, 'kan?",
  ui_story_31210401_22_dialog_content = "...",
  ui_story_31210401_23_dialog_content = "Kenapa kau menatapku begitu, sih? Isi bukunya memang seperti itu, 'kan?",
  ui_story_31210401_24_dialog_content = "Ekspektasimu pada buku ini benar-benar tinggi, ya?",
  ui_story_31210401_25_dialog_content = "Yah... Sepertinya aku sudah tak sabar untuk membaca kisah di dalamnya.",
  ui_story_31210401_26_dialog_content = "Kalau begitu, akan kujelaskan apa isi Lumopolis Temple Scriptures ini.",
  ui_story_31210401_27_dialog_content = "Terutama konsep inti yang ingin disampaikannya.",
  ui_story_31210401_28_dialog_content = "Baiklah!",
  ui_story_31210401_29_dialog_content = "Kita mulai, ya.",
  ui_story_31210401_30_dialog_content = "Pertama-tama, apa yang dibutuhkan seseorang... untuk membuat cerita?",
  ui_story_31210401_31_dialog_content = "Membuat? Kau mau menceritakan kisah-kisah dalam buku ini, 'kan?",
  ui_story_31210401_32_dialog_content = "Diam.",
  ui_story_31210401_33_dialog_content = "Kau harus paham bahwa di tempat seperti Lumopolis, pertama-tama kita perlu menentukan kelas yang berbeda.",
  ui_story_31210401_34_dialog_content = "Karena itu, timbullah perbedaan antara warga biasa dan bangsawan.",
  ui_story_31210401_35_dialog_content = "Bangsawan tentunya memiliki status yang sangat berbeda dengan yang lain. Ini adalah fakta yang tak terbantahkan.",
  ui_story_31210401_36_dialog_content = "Sekarang, kita bahas bagiannya yang paling penting.",
  ui_story_31210401_37_dialog_content = "Ini adalah kisah tentang dua keluarga bangsawan—Keluarga A dan Keluarga B.",
  ui_story_31210401_38_dialog_content = "Keluarga A mencari cara agar putri mereka menerima berkah God of Light.",
  ui_story_31210401_39_dialog_content = "Lalu mereka memutuskan bahwa mengirimnya ke Lumopolis Temple untuk menjadi biarawati adalah keputusan yang bijaksana.",
  ui_story_31210401_40_dialog_content = "Bersih, alim, suci, tidak terpengaruh oleh dunia luar, dan sama sekali tidak terpengaruh oleh kehidupan sekuler.",
  ui_story_31210401_41_dialog_content = "Jadi... Apa sih persisnya tugas biarawati itu?",
  ui_story_31210401_42_dialog_content = "Pertanyaanmu sangat bagus.",
  ui_story_31210401_43_dialog_content = "Para biarawati harus mengakui dosa-dosanya, mengantar kepergian Aurorian yang telah wafat, dan menderita karena pengabaian Tuhan.",
  ui_story_31210401_44_dialog_content = "Tapi, yang paling penting, mereka dengan teguh menganut kepercayaan dan ajaran God of Light.",
  ui_story_31210401_45_dialog_content = "Semua kepercayaan para biarawati berasal dari buku ini—Lumopolis Temple Scriptures.",
  ui_story_31210401_46_dialog_content = "Sang biarawati muda tersebut memahami ajaran itu dengan sangat baik, dan percaya bahwa dia harus menjaga ketakwaannya terhadap God of Light serta menjauhi kehidupan asmara.",
  ui_story_31210401_47_dialog_content = "Menjauhi kehidupan asmara?",
  ui_story_31210401_48_dialog_content = "Oh... Maksudnya percintaan.",
  ui_story_31210401_49_dialog_content = "Bagaimana menurutmu tentang God of Light?",
  ui_story_31210401_50_dialog_content = "Ah! Anu... Yah...",
  ui_story_31210401_51_dialog_content = "God of Light... Aku selalu mendengar orang menyebut nama itu... Kurasa dia...",
  ui_story_31210401_52_dialog_content = "Semacam dewa yang sangat kuat?",
  ui_story_31210401_53_dialog_content = "Kamu percaya dengan adanya dewa di dunia ini?",
  ui_story_31210401_54_dialog_content = "Omong-omong, kau ini jelas-jelas tidak tahu apa pun soal agama. Ayo kita lanjutkan saja kisahnya.",
  ui_story_31210401_55_dialog_content = "...",
  ui_story_31210401_56_dialog_content = "Keluarga A dan Keluarga B hidup secara harmonis, mempelajari sihir bersama, dan saling mengandalkan satu sama lain.",
  ui_story_31210401_57_dialog_content = "Pemerintah Lumopolis sangat mewaspadai orang-orang yang menentang ajaran God of Light.",
  ui_story_31210401_58_dialog_content = "Untuk menghilangkan kecemasan kelas atas, kedua keluarga tersebut melakukan penelitian mereka dengan transparansi penuh...",
  ui_story_31210401_59_dialog_content = "Akhirnya, terciptalah suatu terobosan dengan bimbingan God of Light.",
  ui_story_31210401_60_dialog_content = "Mereka menyanyi untuk surga, memuji-muji White Night, dan bersuka ria dalam iman.",
  ui_story_31210401_61_dialog_content = "Takdir kedua keluarga itu tak bisa dipisahkan dan terjalin selamanya.",
  ui_story_31210401_62_dialog_content = "Sang biarawati muda dari Keluarga A tadi juga sangat puas dengan wahyu ini.",
  ui_story_31210401_63_dialog_content = "Karena dia tahu bahwa berkah ini adalah kehendak God of Light.",
  ui_story_31210401_64_dialog_content = "Sejak saat itu, imannya makin teguh, dan dia pun bersumpah untuk menggunakan segenap waktunya untuk menjalankan tugas sebagai biarawati.",
  ui_story_31210401_65_dialog_content = "Selamanya.",
  ui_story_31210401_66_dialog_content = "...",
  ui_story_31210401_67_dialog_content = "Ada apa?",
  ui_story_31210401_68_dialog_content = "Kok sepertinya kamu ingin mengatakan sesuatu.",
  ui_story_31210401_69_dialog_content = "Selamanya... terdengar sedikit tidak realistis.",
  ui_story_31210401_70_dialog_content = "Dengan sedih, pria itu bertanya kepada keluarganya apakah ada cara untuk memperistri biarawati tersebut.",
  ui_story_31210401_71_dialog_content = "Keluarganya berkata bahwa dia tidak akan dianggap sebagai anak lagi jika berpikir untuk menikahi seorang bangsawan kelas bawah.",
  ui_story_31210401_72_dialog_content = "Pria itu menunjukkan maksudnya dengan jelas. Dia tidak memedulikan konsep dangkal keluarganya tentang status. Yang dia pedulikan hanyalah cinta.",
  ui_story_31210401_73_dialog_content = "Akibatnya, pria itu kehilangan status bangsawannya dan menjadi warga biasa.",
  ui_story_31210401_74_dialog_content = "Dia mencari biarawati itu, menjelaskan situasinya, dan mulai merayunya sekali lagi.",
  ui_story_31210401_75_dialog_content = "Sebenarnya, dia merasa gugup dan siap jika biarawati itu menolaknya lagi...",
  ui_story_31210401_76_dialog_content = "Mata sang biarawati membelalak saking terkejutnya saat mendengar bahwa pria itu bukan lagi seorang bangsawan...",
  ui_story_31210401_77_dialog_content = "Dia pun langsung menerima pinangannya.",
  ui_story_31210401_78_dialog_content = "Karena pria itu sudah menentang keluarganya, sang biarawati itu percaya bahwa dia juga harus menentang ajaran kuil.",
  ui_story_31210401_79_dialog_content = "Tapi... menurut ajaran di buku ini, biarawati itu seharusnya tidak pergi dengannya, 'kan?",
  ui_story_31210401_80_dialog_content = "Ini 'kan hanya cerita, apalagi cerita tentang Lumopolis. Tentu saja akhir kisahnya bahagia.",
  ui_story_31210401_81_dialog_content = "Nah, sekarang bersiaplah mendengar akhir cerita yang adil, indah, dan spektakuler ini—",
  ui_story_31210401_82_dialog_content = "God of Light merasa tersentuh atas keberanian pria itu untuk menentang keluarganya dan ketakwaan sang biarawati yang menolak rayuannya setelah sekian lama. Lalu, dia pun memberkahi mereka dengan cinta.",
  ui_story_31210401_83_dialog_content = "Sejak saat itu, mereka hidup bahagia selama-lamanya dan memiliki tiga orang anak.",
  ui_story_31210401_84_dialog_content = "Yang seperti ini hanya terjadi dalam dongeng.",
  ui_story_31210401_85_dialog_content = "Kamu benar. Ini memang dongeng.",
  ui_story_31210401_86_dialog_content = "Tak kusangka akan ada kisah yang dramatis dan detail dalam buku ini!",
  ui_story_31210401_87_dialog_content = "Tadinya kupikir isinya penuh dengan mitos kuno yang tidak jelas.",
  ui_story_31210401_88_dialog_content = "Kalau ingin tahu lebih banyak, sayangnya kau harus mencaritahunya sendiri dari buku.",
  ui_story_31210401_89_dialog_content = "Baiklah, akan kubaca sendiri!",
  ui_story_31210401_90_dialog_content = "Kalau begitu, aku akan kembali ke kamarku dan membacanya dengan cermat...",
  ui_story_31210401_91_dialog_content = "Terima kasih telah membagikan kisah itu, Paloma! Akan kuberitahukan pendapatku kalau aku sudah selesai membacanya!",
  ui_story_31210401_92_dialog_content = "Dulu, kau menceritakan kisah tentang seorang biarawati dan keluarganya!",
  ui_story_31210401_93_dialog_content = "Kisah tentang rahmat God of Light, kerja sama yang tulus antara dua keluarga, dan akhir cerita yang membahagiakan.",
  ui_story_31210401_94_dialog_content = "Yah, setelah mendengar kisahku, kau membaca buku itu sendiri, 'kan?",
  ui_story_31210401_95_dialog_content = "Sekarang bagaimana menurutmu? Apa buku ini sesuai ekspektasimu?",
  ui_story_31210401_96_dialog_content = "Atau kau lebih suka God and Goddess of Light?",
  ui_story_31210401_97_dialog_content = "Anu... Yah...",
  ui_story_31210401_98_dialog_content = "Sebenarnya... aku tidak begitu paham...",
  ui_story_31210401_99_dialog_content = "Buku ini penuh ajaran agama yang membingungkan... Tapi, aku jadi tidur nyenyak setelah membacanya.",
  ui_story_31210401_100_dialog_content = "Memang.",
  ui_story_31210401_101_dialog_content = "Dan... aku tidak paham apa kaitan isi buku ini dengan kisah yang dulu kamu ceritakan.",
  ui_story_31210401_102_dialog_content = "Tidak ada kisah tentang seorang biarawati muda atau dua keluarga di buku ini...",
  ui_story_31210401_103_dialog_content = "Buku ini hanya penghormatan yang berisi nyanyian puji-pujian untuk God of Light.",
  ui_story_31210401_104_dialog_content = "Ini karena memang tidak ada kisah yang bahagia.",
  ui_story_31210401_105_dialog_content = "Hanya saja, dulu kau terlihat sangat bersemangat ingin membacanya. Jadi, kuceritakan kisah yang selaras dengan konsep intinya.",
  ui_story_31210401_106_dialog_content = "Sayangnya, konsep itu benar-benar keliru.",
  ui_story_31210401_107_dialog_content = "Sekarang kuharap kau sudah siap untuk menghadapi kenyataan—",
  ui_story_31210401_108_dialog_content = "Lagi pula, makin bagus kisahnya, makin kabur kegelapan realitasnya.",
  ui_story_31210401_109_dialog_content = "Dan makin jelas bahwa buku ini pantas ditertawakan.",
  ui_story_31210401_110_dialog_content = "Kegelapan realitas?",
  ui_story_31210401_111_dialog_content = "Jadi... Kisah yang dulu itu bukan kisah yang sederhana, ya?",
  ui_story_31210401_112_dialog_content = "Tentu saja bukan. Sekarang, aku ingin mengungkap akhir cerita yang gelap.",
  ui_story_31210401_113_dialog_content = "Mari kita kembali ke awal \"kerja sama\" antara Keluarga A dan B.",
  ui_story_31210401_114_dialog_content = "Meskipun memiliki kekuatan yang sama, cara pandang mereka dalam penggunaan kekuatan itu sangat bertentangan.",
  ui_story_31210401_115_dialog_content = "Keluarga A melakukan kejahatan yang keji demi mencapai terobosan sihir mereka.",
  ui_story_31210401_116_dialog_content = "Akhirnya, perbuatan memalukan mereka diumumkan dan tidak mungkin dibatalkan.",
  ui_story_31210401_117_dialog_content = "Dengan nama God of Light, Lumopolis beserta Keluarga A dan B dihukum.",
  ui_story_31210401_118_dialog_content = "Mereka ditinggalkan oleh God of Light karena tidak layak berdiri dalam kemuliaannya.",
  ui_story_31210401_119_dialog_content = "Kisah ini... terdengar tidak asing...",
  ui_story_31210401_120_dialog_content = "Hukuman pun tidak luput dari biarawati muda Keluarga A. Dia dikucilkan dari gereja.",
  ui_story_31210401_121_dialog_content = "Dia mengira bahwa ini akan menjadi hukumannya sepenuhnya. Dia tidak menyangka takdirnya akan sepahit ini...",
  ui_story_31210401_122_dialog_content = "Putra dari Keluarga B adalah pemuda yang kejam dan gila.",
  ui_story_31210401_123_dialog_content = "Dia bersumpah akan melakukan apa saja untuk menuntut balas karena dibutakan oleh wewenangnya sebagai bangsawan...",
  ui_story_31210401_124_dialog_content = "Dia melibatkan semua orang dalam akal bulusnya yang gila dan mengakibatkan tragedi yang lebih besar.",
  ui_story_31210401_125_dialog_content = "Yang mana korban dan yang mana pelaku terus silih berganti, dan orang yang tak bersalah terjerumus ke dalam pusaran yang tak terhindarkan itu.",
  ui_story_31210401_126_dialog_content = "Belas kasihan? Pemahaman? Ampunan? Biarawati itu tidak melihat semua ini. Yang dia lihat hanyalah...",
  ui_story_31210401_A1_dialog_content = "Kekejaman membabi buta yang menghancurkan kepercayaannya.",
  ui_story_31210401_127_dialog_content = "Maka, biarawati yang mematuhi Lumopolis Temple Scriptures itu justru mendapati keluarganya dibantai.",
  ui_story_31210401_128_dialog_content = "Nah, sekarang kau sudah tahu. Buku itu berisi ajaran yang sama—",
  ui_story_31210401_129_dialog_content = "Dongeng dan realitas memiliki akhir cerita yang sangat berbeda. Dongeng ya dongeng, tapi lain halnya dengan realitas.",
  ui_story_31210401_130_dialog_content = "Begitulah yang bisa kukatakan tentang buku ini.",
  ui_story_31210401_131_dialog_content = "Lumopolis Temple Scriptures...",
  ui_story_31210401_132_dialog_content = "Kok raut mukamu jadi aneh begitu... Nah, sekarang bagaimana menurutmu?",
  ui_story_31210401_133_dialog_content = "Sepertinya aku paham maksudmu, Paloma. Biarawati itu sebenarnya...",
  ui_story_31210401_134_option_content = "Belum menemukan kepercayaan sejatinya...?",
  ui_story_31210401_135_dialog_content = "Mungkin saja.",
  ui_story_31210401_136_dialog_content = "Tapi, beranggapan bahwa kepercayaannya dulu adalah hal yang salah tidaklah buruk.",
  ui_story_31210401_137_dialog_content = "Apakah tragedi yang dialaminya di masa lalu terlalu berat untuk biarawati itu?",
  ui_story_31210401_138_option_content = "Kamu sudah menemukan kepercayaan sejatimu?",
  ui_story_31210401_139_dialog_content = "Kau benar-benar yakin bahwa ada kepercayaan sejati di dunia ini?",
  ui_story_31210401_140_dialog_content = "Maaf. Aku... aku tidak tahu.",
  ui_story_31210401_141_dialog_content = "Itu tidak penting, kok.",
  ui_story_31210401_142_dialog_content = "Keyakinan tidak boleh menjadi alat yang digunakan oleh segelintir orang untuk mencuci otak banyak orang. Itu yang penting.",
  ui_story_31210401_143_dialog_content = "Keyakinan harus berasal dari dalam hati.",
  ui_story_31210401_144_dialog_content = "Dari dalam hati...",
  ui_story_31210401_145_dialog_content = "Realitas Lumopolis Temple jauh lebih keji dari yang bisa kamu bayangkan.",
  ui_story_31210401_146_dialog_content = "Bergantung pada sistem kelas yang bobrok dan tidak bisa dilewati dalam seumur hidup seseorang.",
  ui_story_31210401_147_dialog_content = "Mungkin... kuil itu hanya bagian dari Lumopolis?",
  ui_story_31210401_148_dialog_content = "Aku pernah bertemu dengan rakyat jelata yang bodoh dan bangsawan yang berprinsip di Lumopolis.",
  ui_story_31210401_149_dialog_content = "Lumopolis adalah kota yang sangat luas dan rumit. Ada begitu banyak orang di sana.",
  ui_story_31210401_A2_dialog_content = "Bukan hanya sesosok God of Light yang tak berwujud.",
  ui_story_31210401_150_dialog_content = "Aku tahu tidak semua orang puas dengan situasinya, dan mereka mencoba memperbaikinya...",
  ui_story_31210401_151_dialog_content = "... Aku mengerti cara pikirmu.",
  ui_story_31210401_152_dialog_content = "Tapi, maafkan aku.",
  ui_story_31210401_153_dialog_content = "Orang-orang yang meyakini bahwa Lumopolis bisa berubah telah gagal memahami inti masalahnya.",
  ui_story_31210401_154_dialog_content = "Struktur aslinya menciptakan kontradiksi yang tak bisa didamaikan.",
  ui_story_31210401_155_dialog_content = "Tapi, semua orang berhak untuk berpendapat... Kalau soal itu, aku tak keberatan.",
  ui_story_31210401_156_dialog_content = "Jadi, pegang teguh cara pandangmu terhadap dunia.",
  ui_story_31210401_157_dialog_content = "Anu... Kau sudah mau pergi?",
  ui_story_31210401_158_dialog_content = "Sebentar, koinmu jatuh, nih!",
  ui_story_31210401_159_dialog_content = "Simpan saja. Anggap saja itu sebagai kenang-kenangan untuk percakapan ini.",
  ui_story_31210401_160_dialog_content = "Selamat tinggal.",
  ui_story_31210601_1_dialog_content = "Ini tempatnya?",
  ui_story_31210601_2_dialog_content = "Itu benar, sekarang mari kita masuk ke dalam.",
  ui_story_31210601_3_dialog_content = "Mengenai Pittman, saya sudah mengaturnya. Apakah kita benar-benar akan melakukan ini?",
  ui_story_31210601_4_dialog_content = "Tentu saja. Lagi pula, sebagai orang kedua di komando <color=#FFB400>Mawar hitam</color>, ini juga bagian dari pekerjaan Anda.",
  ui_story_31210601_5_dialog_content = "Adapun apa yang terjadi jika Anda gagal menepati janji Anda ... Yah, saya pikir saya sudah menjelaskannya dengan sangat jelas kepada Anda, bukan?",
  ui_story_31210601_6_dialog_content = "C-Jelas. Serahkan saja padaku.",
  ui_story_31210601_7_dialog_content = "Harap bersihkan tangan Anda terlebih dahulu, Pak.",
  ui_story_31210601_8_dialog_content = "Baiklah.",
  ui_story_31210601_9_dialog_content = "(Sekarang yang harus saya lakukan adalah memetik buah anggur dan memberikannya kepada Paloma.)",
  ui_story_31210601_10_dialog_content = "(Aku sudah melatihnya di pikiranku berkali-kali, tapi masih terasa canggung...)",
  ui_story_31210601_11_dialog_content = "Sehat? Apa yang kamu tunggu?",
  ui_story_31210601_12_dialog_content = "(D-Dia meraih tanganku...?!)",
  ui_story_31210601_13_dialog_content = "(Dia hanya makan sendiri pada saat ini...)",
  ui_story_31210601_14_dialog_content = "Anda tidak akan pernah menjadikannya sebagai orang kedua saya dengan watak yang kaku.",
  ui_story_31210601_15_dialog_content = "Aku akan melakukan yang lebih baik lain kali.",
  ui_story_31210601_16_dialog_content = "Kenapa kalian hanya berdiri melongo?! Bukankah kalian semua punya pekerjaan yang harus dilakukan ?!",
  ui_story_31210601_17_dialog_content = "Y-Ya!",
  ui_story_31210601_18_dialog_content = "Silakan gunakan saputangan ini untuk menyeka tangan Anda.",
  ui_story_31210601_19_dialog_content = "Dan ini segelas anggur. Nikmatilah.",
  ui_story_31210601_20_dialog_content = "Nah, itu lebih seperti itu. Anda akan menjadi orang kedua yang luar biasa pada tingkat ini, PlayerName.",
  ui_story_31210601_21_dialog_content = "Aku akan menganggap itu sebagai pujian...",
  ui_story_31210601_22_dialog_content = "Baiklah, itu akan dilakukan untuk saat ini. Kita seharusnya tidak membiarkan tamu kita menunggu lebih lama lagi.",
  ui_story_31210601_23_dialog_content = "Hmph. Aku hampir tidak mengenalimu, Paloma.",
  ui_story_31210601_24_dialog_content = "Bergabung dengan geng tanpa berpikir dua kali hanya bertentangan dengan Lumopolis. Apakah tidak ada batasan seberapa rendah Anda bersedia membungkuk?",
  ui_story_31210601_25_dialog_content = "Jangan lupa, kau masih buronan.",
  ui_story_31210601_26_dialog_content = "Saya bebas melakukan apa pun yang saya inginkan dan bergabung dengan grup apa pun yang saya anggap cocok.",
  ui_story_31210601_27_dialog_content = "Selain itu, Lumopolis adalah yang terburuk dari yang terburuk di dunia ini. Siapa pun akan selangkah lebih maju dari mereka!",
  ui_story_31210601_28_dialog_content = "Katakan padaku, apakah antekmu membawaku ke sini hanya agar kamu bisa menertawakan seorang kenalan lama tentang betapa tidak bisa dikenalinya kamu?",
  ui_story_31210601_29_dialog_content = "Sudah kubilang terakhir kali bahwa aku tidak akan menunjukkan belas kasihan jika kita bertemu lagi.",
  ui_story_31210601_30_dialog_content = "Anda menganggap diri Anda terlalu tinggi, Yang Mulia. Jelas, kaulah yang mengejar tumitku selama ini.",
  ui_story_31210601_31_dialog_content = "Aku rela membiarkanmu pergi, tapi karena kau membawa kita ke titik ini, sepertinya aku tidak punya pilihan.",
  ui_story_31210601_32_dialog_content = "Biarkan ini menjadi pertandingan terakhir dengan Lumopolis yang saya putuskan. Pembebasan yang bagus.",
  ui_story_31210601_33_dialog_content = "Tetap saja, saya tidak punya alasan untuk berurusan dengan seseorang yang setingkat dengan Anda secara pribadi.",
  ui_story_31210601_34_dialog_content = "Saya akan meminta orang kedua saya untuk menunjukkan dengan tepat apa yang terjadi jika Anda menjadikan saya musuh.",
  ui_story_31210601_35_dialog_content = "Siap untuk yang terburuk, Yang Mulia?",
  ui_story_31210601_36_dialog_content = "Anda bermaksud mengirim satu kroni untuk melawan hakim Lumopolis?",
  ui_story_31210601_37_dialog_content = "Kamu pikir kamu sangat tangguh, ya? Maafkan ketidaksopanan saya kalau begitu.",
  ui_story_31210601_38_dialog_content = "Urgh—!",
  ui_story_31210601_39_dialog_content = "Dia kedinginan, bos.",
  ui_story_31210601_40_dialog_content = "Bahkan tidak bisa menerima satu pukulan pun, ya? Benar-benar merusak pemandangan.",
  ui_story_31210601_41_dialog_content = "Ikat dia dan bawa dia untukku.",
  ui_story_31210601_42_dialog_content = "Siap, Kapten!",
  ui_story_31210601_43_dialog_content = "Brilian... sungguh brilian! Ha ha ha!",
  ui_story_31210601_44_dialog_content = "Kekuatan dan kelicikanmu membuatku malu, Lady Paloma.",
  ui_story_31210601_45_dialog_content = "Kamu merayuku. Saya senang penampilan saya tidak mengecewakan Anda.",
  ui_story_31210601_46_dialog_content = "Bagaimana mungkin? The Black Roses pastilah sesuatu yang luar biasa, mengingat orang kedua pun bisa menjatuhkan hakim.",
  ui_story_31210601_47_dialog_content = "Meskipun saya belum pernah mendengar tentang geng Anda, saya berharap dapat melihat eksploitasi Anda dalam waktu dekat.",
  ui_story_31210601_48_dialog_content = "Mawar Hitam selalu seagresif kami.",
  ui_story_31210601_49_dialog_content = "Bukankah ini alasan Anda mendekati kami sejak awal?",
  ui_story_31210601_50_dialog_content = "Ah... Pikiran perseptif dan lidahmu yang cepat hanya cocok dengan kecantikanmu, Nyonya.",
  ui_story_31210601_51_dialog_content = "Sejujurnya, perseteruan saya dengan Hall of Justice terjadi bertahun-tahun yang lalu. Mereka selalu rela menindas orang lain dengan peraturan mereka yang tidak berarti—bahkan rakyat mereka sendiri.",
  ui_story_31210601_52_dialog_content = "Anda mendengarnya sendiri sekarang juga. Hall of Justice telah menempatkan hadiah di kepalaku.",
  ui_story_31210601_53_dialog_content = "Mempertimbangkan musuh bersama kami, saya yakin kami dapat bekerja sama dengan baik.",
  ui_story_31210601_54_dialog_content = "Ini akan menjadi kehormatan terbesar saya untuk melakukannya.",
  ui_story_31210601_55_dialog_content = "Pujian Anda dihargai, tapi mari kita mulai bisnis, oke? Ceritakan lebih banyak tentang pekerjaan Anda ini.",
  ui_story_31210601_56_dialog_content = "Langsung ke intinya, saya suka!",
  ui_story_31210601_57_dialog_content = "Saya ingin meminta bantuan organisasi Anda untuk \"membersihkan\" area di bawah yurisdiksi saya.",
  ui_story_31210601_58_dialog_content = "Setelah Anda menyelesaikan pekerjaan Anda, saya akan datang dengan rombongan tentara, kami akan berpura-pura berperang, dan kemudian orang-orang saya akan membiarkan Anda pergi.",
  ui_story_31210601_59_dialog_content = "Setelah itu, kami akan kembali ke Lumopolis untuk mengobati luka kami. Sesampai di sana, saya akan mengklaim bahwa domain saya diserang oleh Eclipsites dan bahwa kami semua musnah.",
  ui_story_31210601_60_dialog_content = "Anda ingin membersihkan wilayah Anda sendiri dari rakyatnya?",
  ui_story_31210601_61_dialog_content = "Mengapa Anda melakukan sesuatu seperti itu pada diri Anda sendiri?",
  ui_story_31210601_62_dialog_content = "Gurun tandus itu tidak memiliki masa depan seperti sekarang. Terikat padanya hanya akan memperlambatku.",
  ui_story_31210601_63_dialog_content = "Saya sudah memiliki sebidang tanah subur di depan mata saya, tetapi tetap berada di tangan lawan politik. Dengan rencana ini, Tuan Kota tidak punya pilihan selain menjadi perantara atas nama saya.",
  ui_story_31210601_64_dialog_content = "Itu akan menjadi tujuan terakhir orang-orang bodoh itu melayaniku.",
  ui_story_31210601_66_dialog_content = "<color=#e8d9bb>Mendering-</color>",
  ui_story_31210601_67_dialog_content = "Pertimbangkan peti permata ini sebagai pembayaran di muka Anda.",
  ui_story_31210601_68_dialog_content = "Jika Anda berhasil, saya bisa menjadikan Anda seorang perwira kehormatan di kota setelah itu jika Anda mau.",
  ui_story_31210601_69_dialog_content = "Hukum akan memihak Anda sekali lagi; Anda tidak perlu hidup dalam bayang-bayang lagi.",
  ui_story_31210601_70_dialog_content = "Anda juga tidak perlu bekerja di hari lain. Persembahan orang-orang akan lebih dari cukup untuk menopang kita semua selama sisa hidup kita!",
  ui_story_31210601_71_dialog_content = "Apa yang kamu katakan? Saya yakin tawaran seperti ini membutuhkan sedikit pertimbangan.",
  ui_story_31210601_72_dialog_content = "Anda bisa melupakan tentang menjadikan saya seorang perwira. Saya selalu melakukan pekerjaan saya sesuai dengan berapa banyak saya dibayar.",
  ui_story_31210601_73_dialog_content = "Selain itu, saya tidak tertarik menjalin hubungan apa pun dengan Lumopolis atau sistem pemerintahan mereka yang busuk.",
  ui_story_31210601_74_dialog_content = "Kamu benar-benar berbeda dari yang lain. Kalau begitu, saya meninggalkan masa depan saya yang cerah dan sejahtera di tangan Mawar Hitam.",
  ui_story_31210601_75_dialog_content = "Kalian para bangsawan Lumopolis yang munafik harus mempercayakan masa depan kalian kepada Dewa Cahaya, bukan kepadaku.",
  ui_story_31210601_76_dialog_content = "Tidak ada yang istimewa tentang saya.",
  ui_story_31210601_77_dialog_content = "Apakah itu sesuatu yang saya katakan? Atau mungkin ada sesuatu tentang tawaran saya yang tidak Anda sukai?",
  ui_story_31210601_78_dialog_content = "Oh tidak, tawaranmu cukup masuk akal. Lebih dari cukup bagi saya untuk mengamankan masa depan yang cerah dan sejahtera bagi diri saya sendiri.",
  ui_story_31210601_79_dialog_content = "Sayangnya, satu-satunya masa depan yang menanti Anda adalah di sel penjara Hall of Justice.",
  ui_story_31210601_80_dialog_content = "Apa?! Kamu... Apa artinya ini?!",
  ui_story_31210601_81_dialog_content = "Ah... aku mengerti! Saya mengerti semuanya sekarang! Kalian berdua bajingan bekerja sama selama ini untuk melibatkanku! Itu saja?!",
  ui_story_31210601_82_dialog_content = "Ya, saya ingat sekarang! Terakhir kali, ketika saya memberi pelajaran kepada rakyat jelata itu, Anda adalah \"biarawati\" yang menyerang saya, bukan? Mawar Hitam!",
  ui_story_31210601_83_dialog_content = "Penyamaran yang sangat brilian. Aku bahkan tidak mengenalimu.",
  ui_story_31210601_84_dialog_content = "Adapun Anda, Yang Mulia... Anda adalah orang yang menghentikannya menyerang saya, jika saya tidak salah?",
  ui_story_31210601_85_dialog_content = "Tidak kusangka, kalian berdua bekerja sama selama ini hanya untuk menjebakku...",
  ui_story_31210601_86_dialog_content = "Anda salah memahami kedalaman kerja sama kami.",
  ui_story_31210601_87_dialog_content = "Saya hanya menghentikannya saat itu karena, terlepas dari perilaku keji Anda, Anda tidak melanggar hukum Lumopolis.",
  ui_story_31210601_88_dialog_content = "Saya memiliki kewajiban untuk melindungi warga negara Lumopolis yang sah, termasuk Anda sendiri. Tindakan saya hari itu tidak dilatih dengan cara apa pun.",
  ui_story_31210601_89_dialog_content = "Pada catatan itu, Anda harus tahu... Tidak ada organisasi seperti \"Mawar Hitam\", dan saya bukan bos geng.",
  ui_story_31210601_90_dialog_content = "Adapun \"antek\" saya, jika Anda memperhatikan lebih dekat, Anda mungkin mengenali beberapa wajah mereka.",
  ui_story_31210601_91_dialog_content = "Setelah memanfaatkan kami begitu lama... Jangan bilang kamu tidak ingat bagaimana penampilan kami?",
  ui_story_31210601_92_dialog_content = "Kamu orang...",
  ui_story_31210601_93_dialog_content = "Mereka semua adalah orang-orang dari domain Anda. orang-orang ANDA.",
  ui_story_31210601_94_dialog_content = "Dasar lintah terkutuk... Kaulah yang menyedot kehidupan dari tanah kami!",
  ui_story_31210601_95_dialog_content = "Lupakan rumah kami, kamu bahkan tidak peduli dengan hidup kami! Hari ini kami akan memberi Anda pelajaran yang tidak akan pernah Anda lupakan!",
  ui_story_31210601_96_dialog_content = "Anda rubes yang tidak punya uang... Anda harus berterima kasih atas kesempatan untuk bekerja untuk saya!",
  ui_story_31210601_97_dialog_content = "Jika Anda sangat ingin berkelahi, izinkan saya mengembalikan Anda ke tempat Anda!",
  ui_story_31210601_98_dialog_content = "Pria! Untuk saya!",
  ui_story_31210601_99_dialog_content = "\"Pria\"? Maksudmu orang-orang bodoh yang menyesal ini?",
  ui_story_31210601_100_dialog_content = "Maaf mengecewakan Anda, tetapi mereka telah diikat untuk sementara waktu sekarang.",
  ui_story_31210601_101_dialog_content = "(Sialan... Sialan semuanya! Tidak bisa berakhir seperti ini! Pasti ada jalan...)",
  ui_story_31210601_102_dialog_content = "Tunggu, Yang Mulia! Tentunya, Anda tidak punya urusan dengan wanita gila seperti dia.",
  ui_story_31210601_103_dialog_content = "Bantu saya meninggalkan tempat ini dengan aman, dan saya akan melakukan segala daya saya untuk mendorong Anda melewati barisan!",
  ui_story_31210601_104_dialog_content = "Bahkan posisi Ketua Juri pun tidak luput dari pertanyaan!",
  ui_story_31210601_105_dialog_content = "Oh? Perubahan sikap yang tiba-tiba.",
  ui_story_31210601_106_dialog_content = "Bukankah tugas Anda untuk melindungi keselamatan dan kemakmuran para bangsawan Lumo?",
  ui_story_31210601_107_dialog_content = "Ini bisa menjadi kesempatan Anda untuk menunjukkan kepada kami kesetiaan Anda yang tak tergoyahkan! Pikirkan tentang itu!",
  ui_story_31210601_108_dialog_content = "Selama mereka tidak menyerangmu, aku tidak punya alasan untuk ikut campur.",
  ui_story_31210601_109_dialog_content = "Selain itu, saya merasa harus mengoreksi salah satu pernyataan Anda.",
  ui_story_31210601_110_dialog_content = "Loyalitas saya yang tak tergoyahkan adalah kepada Dewa Cahaya, dan tugas saya adalah menegakkan keadilan dan ketertiban di Lumopolis, bukan kepentingan kelas bangsawan.",
  ui_story_31210601_111_dialog_content = "Apa yang kau bicarakan?! Mereka jelas mengancam saya barusan! Apakah kamu tidak mendengarkan ?!",
  ui_story_31210601_112_dialog_content = "Atau apakah \"keadilan\" yang Anda nilai ini suka dibicarakan tidak lebih dari formalitas kosong ?!",
  ui_story_31210601_113_dialog_content = "Anda aman untuk membuat komentar kasar terhadap warga Anda sendiri sebelumnya, bukan?",
  ui_story_31210601_114_dialog_content = "Hukum berlaku untuk semua orang secara setara, dan situasi ini tidak berbeda.",
  ui_story_31210601_115_dialog_content = "Anda tidak kurang munafik dari saya! Terutama kamu, Paloma... Kamu yang terburuk dari semuanya!",
  ui_story_31210601_116_dialog_content = "Anda berbicara tentang membenci Lumopolis dengan sepenuh hati, namun Anda bersedia berkonspirasi dengan salah satu hakim mereka!",
  ui_story_31210601_117_dialog_content = "Saya bersedia mengakui kemunafikan saya sendiri. Apakah kamu?",
  ui_story_31210601_118_dialog_content = "Hmph—!",
  ui_story_31210601_119_dialog_content = "Saya tidak seperti Anda. Bertindak sopan dan baik di depan bangsawan, sambil memperlakukan rakyat jelata tanpa sedikit pun kesopanan.",
  ui_story_31210601_120_dialog_content = "Dan saya tidak pernah mengklaim bahwa apa yang saya lakukan hari ini adalah untuk hakim Lumopolis. Saya melakukan semuanya untuk diri saya sendiri.",
  ui_story_31210601_121_dialog_content = "Tindakan Anda membuat saya sakit perut hari itu, jadi saya memilih untuk berurusan dengan Anda. Sesederhana itu.",
  ui_story_31210601_121X1_dialog_content = "Jika PlayerName tidak memberi tahu saya sebelumnya, saya akan percaya bahwa Anda benar-benar bergabung dengan geng.",
  ui_story_31210601_122_dialog_content = "<color=#e8d9bb>Beberapa jam sebelumnya...</color>",
  ui_story_31210601_123_dialog_content = "Pittman! Disini!",
  ui_story_31210601_124_dialog_content = "PlayerName? Sedang apa kamu di sini?",
  ui_story_31210601_125_dialog_content = "Dan kenapa kamu berpakaian seperti anggota geng?",
  ui_story_31210601_126_dialog_content = "Tidak ada waktu untuk menjelaskan! Ikut saja denganku! Buru-buru!",
  ui_story_31210601_127_dialog_content = "T-Tunggu! Saya masih memiliki urusan mendesak yang harus saya hadiri!",
  ui_story_31210601_128_dialog_content = "Beberapa hari yang lalu, seorang bangsawan Lumopolis berpapasan dengan Paloma, dan aku nyaris tidak bisa campur tangan sebelum situasinya memburuk.",
  ui_story_31210601_129_dialog_content = "Tapi setelah itu, sepertinya Paloma tidak siap untuk melepaskan masalah ini... Aku khawatir dia akan melakukan sesuatu yang buruk.",
  ui_story_31210601_130_dialog_content = "Itu sebabnya aku tidak bisa pergi denganmu sekarang. Mohon maafkan saya.",
  ui_story_31210601_131_dialog_content = "Paloma yang memintaku untuk datang mencarimu, Pittman!",
  ui_story_31210601_132_dialog_content = "Oh, dan jangan lupa! Anda harus berpura-pura tersingkir oleh saya nanti; membuatnya terlihat nyata sehingga tidak terlihat seperti akting!",
  ui_story_31210601_133_dialog_content = "Anda ingin saya berakting...? Saya tidak begitu mengerti... Apakah ini sesuatu yang dibuat oleh Paloma?",
  ui_story_31210601_134_dialog_content = "Jangan khawatir tentang itu! Anda akan mengerti semuanya begitu Anda melihat apa yang terjadi antara Paloma dan bangsawan itu, oke?",
  ui_story_31210601_135_dialog_content = "Dia tidak akan melakukan sesuatu yang ilegal, aku janji! Aku percaya padanya, dan kau percaya padaku... Benar?",
  ui_story_31210601_136_dialog_content = "Meskipun saya telah mempersiapkan diri secara mental, saya masih agak terkejut saat saya melangkah masuk.",
  ui_story_31210601_137_dialog_content = "Betulkah? Bagaimana denganmu, PlayerName?",
  ui_story_31210601_138_option_content = "Ini semua berkat penyamaranmu.",
  ui_story_31210601_139_dialog_content = "Pakaian itu benar-benar menekankan kehadiran Anda yang keren dan mengesankan.",
  ui_story_31210601_140_dialog_content = "Meskipun aku berdiri tepat di sebelahmu, aku bersumpah aku berdiri di samping bos geng sungguhan!",
  ui_story_31210601_141_option_content = "Kepribadian Anda membawa pertunjukan.",
  ui_story_31210601_142_dialog_content = "Rasanya seolah-olah Anda dilahirkan untuk berperan sebagai pemimpin Black Roses.",
  ui_story_31210601_143_dialog_content = "Bahkan saya kesulitan mengingat bahwa Anda bukan pemimpin geng yang kejam!",
  ui_story_31210601_144_dialog_content = "Itu tidak membantu bahwa pakaian ini tampaknya langsung dari lemari pakaian pribadi Anda.",
  ui_story_31210601_145_dialog_content = "Hmph. Anda mulai terdengar seperti kroni yang sebenarnya dengan semua sanjungan itu.",
  ui_story_31210601_146_dialog_content = "Saya harus mengatakan, meskipun... pakaian itu juga sangat cocok untuk Anda, PlayerName.",
  ui_story_31210601_147_dialog_content = "Apakah Anda yakin tidak ingin tetap menjadi tangan kanan saya?",
  ui_story_31210601_148_dialog_content = "H-hah?!",
  ui_story_31210601_149_dialog_content = "*Terkekeh* Aku hanya bercanda.",
  ui_story_31210601_150_dialog_content = "Selain itu, saya bekerja lebih baik sendiri. Saya tidak akan pernah melakukan sesuatu yang bodoh atau merepotkan seperti bergabung dengan geng.",
  ui_story_31210601_151_dialog_content = "Fakta bahwa kamu tidak pernah bermaksud menyerang bangsawan itu menunjukkan bahwa kamu sudah cukup dewasa, Paloma.",
  ui_story_31210601_152_dialog_content = "Siapa, dia? Tolong, dia adalah sasaran yang mudah. Selain itu, saya tidak merasa ingin mengotori duri saya.",
  ui_story_31210601_153_dialog_content = "Meskipun aku sama terkejutnya dengan seseorang yang keras kepala dan usil sepertimu berdiri diam di samping sementara itu semua terjadi. Kamu juga sudah sedikit dewasa, Pittman.",
  ui_story_31210601_154_dialog_content = "Saya hanya memilih untuk mempercayai Anda dan PlayerName kali ini... serta kemampuan saya sendiri untuk merespon dengan cepat, jika situasi membutuhkannya.",
  ui_story_31210601_155_dialog_content = "Juga, saya tidak punya keinginan untuk menangkap Anda sendiri, itulah sebabnya saya tidak akan membiarkan Anda melakukan sesuatu yang ilegal di depan saya.",
  ui_story_31210601_156_dialog_content = "Cukup percaya diri, bukan, Yang Mulia?",
  ui_story_31210601_157_dialog_content = "Orang-orang di luar berpakaian putih pasti dari Hall of Justice.",
  ui_story_31210601_158_dialog_content = "Bala bantuanmu datang lebih cepat dari yang kukira.",
  ui_story_31210601_159_dialog_content = "Dia tidak bercanda. Jalanan penuh dengan Penjaga Lumo!",
  ui_story_31210601_160_dialog_content = "Maksudmu kau tidak menelepon mereka?",
  ui_story_31210601_161_dialog_content = "Tidak, saya tidak. Apakah kamu?",
  ui_story_31210601_162_dialog_content = "Apakah itu dia?",
  ui_story_31210601_163_dialog_content = "Paloma hilang...",
  ui_story_31210601_164_dialog_content = "Jadi... ini Mawar Hitam, ya?",
  ui_story_31210601_165_dialog_content = "Betapa sangat menyukainya.",
  ui_story_31210602_1_dialog_content = "Ah... mata yang bercahaya, wajah yang dianugerahkan oleh dewa... seperti melihat dewa!",
  ui_story_31210602_2_dialog_content = "Betapa megahnya, dewa yang saya sembah... dewi saya...!",
  ui_story_31210602_3_dialog_content = "Ah... Betapa segarnya angin laut ini!",
  ui_story_31210602_4_dialog_content = "Eveetiap kali aku pergi ke pantai, aku merasa sangat senang. Jadi, sekarang aku harus apa?",
  ui_story_31210602_5_option_content = "Pilih kerang yang indah",
  ui_story_31210602_6_dialog_content = "Mungkin saya bisa menghias Colossus dengan beberapa kerang cantik ini.",
  ui_story_31210602_7_dialog_content = "Ada cukup banyak di sini. Sepertinya aku menang jackpot.",
  ui_story_31210602_8_option_content = "Berbaring di pasir",
  ui_story_31210602_9_dialog_content = "Pasir di sini sangat halus dan lembut, saya tidak bisa menahan diri untuk berbaring di atasnya.",
  ui_story_31210602_10_dialog_content = "Hah? Apa ini duri hitam di pasir? Seseorang mungkin terluka karena itu... Sepertinya aku harus mencabutnya.",
  ui_story_31210602_11_dialog_content = "Sedang apa kau?",
  ui_story_31210602_12_dialog_content = "Eh?! Apa yang kamu lakukan di sana di pasir?",
  ui_story_31210602_13_dialog_content = "Aku hanya berbaring di sini menikmati sinar matahari sampai kamu mulai menarik pakaian renangku.",
  ui_story_31210602_14_dialog_content = "S-Maaf, saya kira itu semacam paku...",
  ui_story_31210602_15_dialog_content = "Jika kamu benar-benar ingin minta maaf, saya ingin kamu menemani saya ke suatu tempat.",
  ui_story_31210602_16_dialog_content = "Eh... Di mana?",
  ui_story_31210602_17_dialog_content = "Pernahkah kamu mendengar tentang sekte misterius di sini yang memuja Dewi Firethorn?",
  ui_story_31210602_18_dialog_content = "Dewi Firethorn? Tidak pernah dengar tentangnya.",
  ui_story_31210602_19_dialog_content = "Orang biasa sangat suka menciptakan dewa-dewa kecil palsu seperti itu.",
  ui_story_31210602_20_dialog_content = "Kecerdasan yang telah saya peroleh menunjukkan bahwa ada sesuatu yang tidak beres tentang sekte ini, dan saya berencana untuk menginvestigasinya.",
  ui_story_31210602_21_dialog_content = "Itu terdengar agak berbahaya. Aku akan pergi denganmu.",
  ui_story_31210602_22_dialog_content = "Tapi sebelum kita berangkat, saya perlu ganti pakaian saya menjadi pakaian biasa.",
  ui_story_31210602_23_dialog_content = "Hei, apa yang kalian berdua lakukan? Orang luar tidak diterima di sini! Pergi kalian!",
  ui_story_31210602_24_dialog_content = "<size=30>Kita harus bagaimana? Mereka tidak akan membiarkan kita masuk...</size>",
  ui_story_31210602_25_dialog_content = "<size=30>Jangan khawatir, serahkan ini padaku.</size>",
  ui_story_31210602_26_dialog_content = "Kami anggota baru dari kawanan ini dan ingin berpartisipasi dalam upacara hari ini.",
  ui_story_31210602_27_dialog_content = "Darah baru, eh? Ada bukti? Apakah kamu membawa lambang Dewi Firethorn?",
  ui_story_31210602_28_dialog_content = "Lambang Dewi Firethorn?",
  ui_story_31210602_29_dialog_content = "Ini—",
  ui_story_31210602_30_dialog_content = "(Dia baru saja mencabut sepotong duri tajam pendek. Sepertinya permainannya sudah berakhir, tidak ada cara kita bisa lewat darinya!)",
  ui_story_31210602_31_dialog_content = "Apakah ini yang sedang kamu bicarakan?",
  ui_story_31210602_32_dialog_content = "(Hah? Paloma sebenarnya punya salah satu dari itu?)",
  ui_story_31210602_33_dialog_content = "Benar. Ini adalah hadiah yang diberikan kepada kita oleh Dewi Firethorn—sebuah hadiah yang hanya bisa dimiliki oleh orang yang benar-benar percaya.",
  ui_story_31210602_34_dialog_content = "Kamu seharusnya menunjukkannya lebih awal kepadaku. Kamu boleh memasuki.",
  ui_story_31210602_35_dialog_content = "Bagaimana kamu mendapatkan hal sigil itu?",
  ui_story_31210602_36_dialog_content = "Tebak.",
  ui_story_31210602_37_dialog_content = "Kamu berhasil melakukannya dengan kekuatanmu.",
  ui_story_31210602_38_dialog_content = "Kurasa kamu ternyata tidak begitu membosankan.",
  ui_story_31210602_39_dialog_content = "Sungguh kebetulan kamu bisa mengendalikan duri... Untung saja simbol itu bukan batangan cokelat.",
  ui_story_31210602_40_dialog_content = "Apakah kamu benar-benar percaya itu kebetulan?",
  ui_story_31210602_41_dialog_content = "Apa?",
  ui_story_31210602_42_dialog_content = "Sepertinya upacara belum dimulai. Mari mencari tempat di mana kita bisa menyaksikannya dari bayangan.",
  ui_story_31210602_43_dialog_content = "Sangat redup di sini. Saya pikir semua upacara keagamaan dilakukan di tempat yang terang dan terbuka.",
  ui_story_31210602_44_dialog_content = "Tidak semua gereja mengikuti terang. Mungkin kita hanya akan menemukan mantra misterius dan persembahan di sini, atau bahkan mungkin pengorbanan...",
  ui_story_31210602_45_dialog_content = "Jangan menakutiku, saya tidak ingin dihidangkan seperti domba di mezbah.",
  ui_story_31210602_46_dialog_content = "Jangan khawatir. Gerombolan ini belum berani untuk mengorbankan orang yang masih hidup.",
  ui_story_31210602_47_dialog_content = "Para penganut yang sejati, selamat datang di upacara hari ini. Saya adalah utusan dari Pendeta.",
  ui_story_31210602_48_dialog_content = "Hari ini, kami menawarkan pengorbanan paling berharga kami kepada Dewi Firethorn—sebagai ungkapan cinta dan penghargaan kami kepada-Nya.",
  ui_story_31210602_49_dialog_content = "Puji Dewi Firethorn! Puji sang Pendeta!",
  ui_story_31210602_50_dialog_content = "Aku lihat ada beberapa wajah baru di antara kita hari ini. Tentu saja, kami menyambut baik tambahan darah segar, tetapi terlebih dahulu kamu perlu memberikan kami tawaranmu.",
  ui_story_31210602_51_dialog_content = "Hanya setelah disetujui oleh para arbiter kami, Anda dapat resmi bergabung dengan kami.",
  ui_story_31210602_52_dialog_content = "Jenis persembahan apa? Mereka tidak akan melakukan apa-apa pada kita, kan?",
  ui_story_31210602_53_dialog_content = "Mari lihat apa yang dilakukan orang lain terlebih dahulu.",
  ui_story_31210602_54_dialog_content = "Saya punya persembahan! Saya ingin menyerahkannya!",
  ui_story_31210602_55_dialog_content = "Seorang pengikut yang bersemangat. Bagus sekali! Silakan bergabung dengan saya di panggung.",
  ui_story_31210602_56_dialog_content = "Ini adalah foto yang saya ambil dari bintang laut. Saya rasa sangat indah dan cocok untuk mengungkapkan rasa hormat saya kepada Dewi Firethorn.",
  ui_story_31210602_57_dialog_content = "Bintang laut? Kamu ingin menawarkan bintang laut kepada Dewi Firethorn? Apakah kamu pikir bintang laut biasa bisa menyentuh hatinya?",
  ui_story_31210602_58_dialog_content = "Uh, sebenarnya, menurut saya bintang laut yang dia foto itu sangat lucu.",
  ui_story_31210602_59_dialog_content = "Apakah kamu lupa fokus dari ajaran kita saat ini? Apakah kamu benar-benar percaya bahwa Pendeta ingin melihat sesuatu yang begitu medioker dan tidak menarik? Berikutnya.",
  ui_story_31210602_60_dialog_content = "Halo semua. Foto yang ingin saya bagikan kepada kalian adalah seekor penyu laut, yang merupakan jenis dari...",
  ui_story_31210602_61_dialog_content = "Nol poin.",
  ui_story_31210602_62_dialog_content = "Nol poin.",
  ui_story_31210602_63_dialog_content = "Lima poin. Itu adalah tembakan yang hebat. Kura-kura memiliki rentang hidup yang sangat panjang. Mereka pasti menyimpan banyak cerita dan rahasia.",
  ui_story_31210602_64_dialog_content = "Kura-kura hanyalah reptil yang lambat dan membosankan. Kamu bisa mendapatkan foto-foto ini di mana saja. Mereka tidak bernilai.",
  ui_story_31210602_65_dialog_content = "Kami adalah klub fotografi biologi kelautan, dan meskipun sekarang kami menjadi—",
  ui_story_31210602_66_dialog_content = "Diam! Berikutnya!",
  ui_story_31210602_67_dialog_content = "Beberapa hakim ini benar-benar keras, tetapi sejauh ini, tampaknya gereja ini pada dasarnya hanya sekelompok fotografer kehidupan laut.",
  ui_story_31210602_68_dialog_content = "Mereka masing-masing memiliki sepotong kecil firethorn. Apa, beritahu, apa hubungannya dengan makhluk laut?",
  ui_story_31210602_69_dialog_content = "Hmm... sepertinya tidak ada koneksi di sana.",
  ui_story_31210602_70_dialog_content = "Jadi, pasti ada sesuatu yang lebih dalam terjadi dengan sekte ini.",
  ui_story_31210602_71_dialog_content = "Lagipula, keseruan baru saja akan dimulai.",
  ui_story_31210602_72_dialog_content = "Apa maksudmu?",
  ui_story_31210602_73_dialog_content = "Lampu telah redup, gerbang telah ditutup, dan lilin biru telah dinyalakan... Ah, upacara palsu penuh tipu daya yang diberkati ini akan segera dimulai.",
  ui_story_31210602_74_dialog_content = "Pastor besar telah tiba, mari kita semua menyambutnya dengan tepuk tangan yang paling hangat!",
  ui_story_31210602_75_dialog_content = "Puji Dewi Firethorn! Puji sang Pendeta!",
  ui_story_31210602_76_dialog_content = "Terima kasih semua telah datang ke upacara persembahan bulanan kami. Dewi Firethorn Yang Maha Kuasa menantikan untuk menerima persembahan murni yang telah kalian kumpulkan di sini untuk dipersembahkan.",
  ui_story_31210602_77_dialog_content = "(Persembahan murni? Apakah dia maksud emas dan perhiasan atau sesuatu seperti itu?)",
  ui_story_31210602_78_dialog_content = "Yang Mulia, izinkan saya mengatakan beberapa kata. Kami baru saja menilai persembahan yang dibawa oleh beberapa pendatang baru dan menemukan bahwa mereka sangat kurang!",
  ui_story_31210602_79_dialog_content = "Tapi saya tidak ingin terlalu keras pada mereka. Jelas, mereka gagal memahami aturan upacara dan butuh waktu untuk menyesuaikan diri dengan cara kita.",
  ui_story_31210602_80_dialog_content = "Sekarang, kita akan mulai memperlihatkan penawaran sebenarnya. Melihat!",
  ui_story_31210602_81_dialog_content = "Oh, ini mengagumkan.",
  ui_story_31210602_82_dialog_content = "Pencahayaan dan komposisi sangat sempurna, hampir tak ada cacatnya!",
  ui_story_31210602_83_dialog_content = "Saya juga telah menyiapkan persembahan untuk Dewi Firethorn! Ini adalah foto-foto spontan yang saya ambil dari beberapa gadis di pantai!",
  ui_story_31210602_84_dialog_content = "Wow! Lihat saja persembahanmu! Mereka benar-benar istimewa! Dewi Firethorn pasti akan menyukai ini!",
  ui_story_31210602_85_dialog_content = "Ini menjijikkan! Orang-orang ini tidak lebih dari pengintip! Sungguh sekumpulan orang cabul!",
  ui_story_31210602_86_dialog_content = "Pastor, kumohon! Izinkan kami memandang Dewi Firethorn sekali lagi!",
  ui_story_31210602_87_dialog_content = "Baiklah. Saatnya telah tiba untuk mengundang Dewi ke altar agar semua dari kalian dapat menyembah.",
  ui_story_31210602_88_dialog_content = "Salam, Dewi—",
  ui_story_31210602_89_dialog_content = "Hah? Dewi Firethorn itu... sebuah foto?",
  ui_story_31210602_90_dialog_content = "Apa garis hitam yang bersilang-silang ini di foto? Saya tidak mengerti, tetapi entah mengapa terasa familiar...",
  ui_story_31210602_91_dialog_content = "Jadi, dia yang melakukannya!",
  ui_story_31210602_92_dialog_content = "Hah? Kamu menemukan sesuatu?",
  ui_story_31210602_93_dialog_content = "Duri-duri saya akan segera mencekik kehidupan dari kuil keinginan dan dosa yang rusak ini.",
  ui_story_31210602_94_dialog_content = "Darah segar, apakah kamu sekarang mengerti jenis foto yang harus kamu ambil?",
  ui_story_31210602_95_dialog_content = "Nah, ini semua cukup aneh, tapi sepertinya sangat menarik pada saat yang sama. Saya bersedia untuk bergabung!",
  ui_story_31210602_96_dialog_content = "Saya merasa agak malu karena usia saya yang lanjut, tetapi saya juga bersedia mengikuti Pendeta dan Dewi Firethorn!",
  ui_story_31210602_97_dialog_content = "Mengapa kedua orang baru di pojok itu tidak mengatakan apa-apa? Kamu belum memberikan persembahan apa pun, bukan? Sekarang kamu bisa minta Pendeta itu sendiri untuk memandu kamu.",
  ui_story_31210602_98_dialog_content = "Oh tidak, mereka telah melihat kita.",
  ui_story_31210602_99_dialog_content = "Di sini, kamu bisa ambil foto ini sebagai tawaran.",
  ui_story_31210602_100_dialog_content = "Hmm? Bukankah itu—!",
  ui_story_31210602_101_dialog_content = "Buruan sekarang! Jangan buang waktu Pendeta!",
  ui_story_31210602_102_dialog_content = "Um, saya... Foto ini...",
  ui_story_31210602_103_dialog_content = "Biarku lihat-",
  ui_story_31210602_104_dialog_content = "Ini bukan Dewi Firethorn?!",
  ui_story_31210602_105_dialog_content = "Siapa kamu? Bagaimana mungkin kamu memiliki foto Dewi Firethorn?!",
  ui_story_31210602_106_dialog_content = "Tahu kah kamu di mana kita bisa menemukan Dewi Firethorn? Seseorang! Siapapun! Tangkap dia!",
  ui_story_31210602_107_dialog_content = "Aku tidak tahu apa-apa...",
  ui_story_31210602_108_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_109_dialog_content = "Bagaimana berani kamu menyentuhnya!",
  ui_story_31210602_110_dialog_content = "Astaga! Itu Dewi Firethorn! Dia telah turun!",
  ui_story_31210602_111_dialog_content = "(Bagaimana Paloma bisa mengganti pakaiannya begitu cepat?)",
  ui_story_31210602_112_dialog_content = "Saatnya sandiwara absurd ini berakhir.",
  ui_story_31210602_113_dialog_content = "Argh! Duri yang ganas! Apakah ini sifat asli Dewi Firethorn yang kusembah?",
  ui_story_31210602_114_dialog_content = "Dewi, saya adalah pengikut setia Anda yang paling setia! Merupakan kehormatan tertinggi bisa berada di hadapan Anda!",
  ui_story_31210602_115_dialog_content = "Tutup mulutmu!",
  ui_story_31210602_116_dialog_content = "Aaaaaahhhh!",
  ui_story_31210602_117_dialog_content = "Apakah ini cara Dewi dan Pendeta seharusnya bisa akrab? Semua ini terasa sedikit terlalu intens untukku...",
  ui_story_31210602_118_dialog_content = "Bukan itu. Dia teman saya, bukan Dewi dari sekte kecil yang terpelintir milikmu. Kalian semua telah ditipu oleh Pendeta.",
  ui_story_31210602_119_dialog_content = "Sakit, sakit! Kayaknya aku mau mati!",
  ui_story_31210602_120_dialog_content = "Apakah kamu bersedia mengungkap kebenaran di balik sekte yang disebut-sebut ini sekarang? Ceritakan dari awal.",
  ui_story_31210602_121_dialog_content = "*Hiks* Aku akan memberitahu! Aku akan memberitahu semuanya!",
  ui_story_31210602_122_dialog_content = "Sekte ini awalnya adalah masyarakat fotografi kehidupan laut. Saya hanya salah satu anggota, tetapi minat sejati saya sulit untuk diungkapkan...",
  ui_story_31210602_123_dialog_content = "Di bawah pengaruh saya, klub kecil ini perlahan berubah menjadi perkumpulan eksentrik.",
  ui_story_31210602_124_dialog_content = "Beberapa bulan yang lalu, di pantai, saya mengambil foto kamu mengenakan baju renang yang cantik, dan sejak itu saya ingin melihatnya lagi.",
  ui_story_31210602_125_dialog_content = "Ketika saya memperlihatkan foto Anda di pertemuan fotografi kami, setiap orang mulai kagum dengan kecantikan ilahi Anda—seperti seorang dewi.",
  ui_story_31210602_126_dialog_content = "Dulu saya kesulitan dengan masalah uang... Eh, tidak, saya ingin menagih anggota, u-untuk mendukung pengembangan masyarakat!",
  ui_story_31210602_127_dialog_content = "Jadi, saya menggunakan foto-foto Anda untuk membuat seri cerita tentang Dewi Firethorn, dan kami secara bertahap mengembangkannya menjadi apa yang kita miliki hari ini...",
  ui_story_31210602_128_dialog_content = "Begitu cerita di balik pendirian gereja itu. Saya perlu mencatatnya dalam Buku Doktrin untuk para penganut di masa depan...",
  ui_story_31210602_129_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_130_dialog_content = "Oh, tidak! Buku Ajaran telah dihancurkan menjadi serpihan!",
  ui_story_31210602_131_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_132_dialog_content = "Argh! Pukulan yang sangat brutal! Sakitnya!",
  ui_story_31210602_133_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_134_dialog_content = "Dewi, tenangkan kemarahanmu! Tolong, Dewi, tolong berhenti mencambuk saya! Ahhhh!",
  ui_story_31210602_135_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_136_dialog_content = "Keinginan memalukan telah menguasai jiwa dan akal Anda. Doktrin yang Anda klaim hanyalah topeng kepura-puraan.",
  ui_story_31210602_137_dialog_content = "Jika kamu melanjutkan perbuatan tercela ini, kebenaran akan menghancurkanmu tanpa belas kasihan!",
  ui_story_31210602_138_dialog_content = "Ah! Berhenti dengan cambukan! Kami tidak akan mengambil foto diam-diam dari gadis-gadis cantik lagi, saya bersumpah pada Fireth—Tidak, saya bersumpah pada Dewa Terang!",
  ui_story_31210602_139_dialog_content = "Sumpah demi Tuhan Terang! Aku takkan pernah melakukan hal seperti ini lagi!",
  ui_story_31210602_140_dialog_content = "Oh, jadi kamu semua dari Lumopolis, itu menjelaskan banyak hal.",
  ui_story_31210602_141_dialog_content = "Fiuh, akhirnya kita menyerahkan penjahat-penjahat itu ke Balai Keadilan.",
  ui_story_31210602_142_dialog_content = "Paloma menyebut ingin pergi ke pantai untuk bersantai. Aku harus menemukannya... Mungkin dia butuh sedikit penyemangat setelah kejadian itu.",
  ui_story_31210602_143_dialog_content = "(Paloma sedang... mengamati bintang laut kecil?)",
  ui_story_31210602_144_dialog_content = "(Dari ekspresi bahagianya, sepertinya dia menikmati kesendirian. Lebih baik aku tidak mengganggunya.)",
  ui_story_31210602_145_dialog_content = "Apakah kamu datang ke sini hanya untuk pergi?",
  ui_story_31210602_146_dialog_content = "Aku tidak ingin mengganggumu, jadi...",
  ui_story_31210602_147_dialog_content = "Apakah semuanya sudah diurus?",
  ui_story_31210602_148_dialog_content = "Ya, Gedung Keadilan sudah mulai penyelidikan.",
  ui_story_31210602_149_dialog_content = "Terima kasih banyak untuk segalanya. Saya beruntung memiliki kamu di sekitar untuk membantu saya mengatasi gangguan yang tak tertahankan dalam berurusan dengan The Hall of Justice.",
  ui_story_31210602_150_dialog_content = "Untuk apa teman? Kamu merasa lebih baik sekarang?",
  ui_story_31210602_151_dialog_content = "Sepertinya kamu salah paham tentang aku. Apakah kamu benar-benar melihat aku sebagai tipe orang yang mudah terganggu oleh masalah sepele seperti itu?",
  ui_story_31210602_152_dialog_content = "Tidak, hanya saja kebanyakan orang mungkin tidak akan merasa terlalu baik tentang apa yang terjadi.",
  ui_story_31210602_153_dialog_content = "Tentu saja, terutama para gadis yang mengalami pelecehan.",
  ui_story_31210602_154_dialog_content = "Mereka awalnya berniat untuk menikmati masa tinggal yang indah di sini, tetapi jahatnya mereka dianiaya oleh penjahat licik.",
  ui_story_31210602_155_dialog_content = "Ya... Bagus kamu berhasil tangkap penjahat sebelum foto-foto itu menjadi viral.",
  ui_story_31210602_156_dialog_content = "Even jika foto-foto itu menyebar ke seluruh benua, bukan gadis-gadis itu yang seharusnya merasa malu dan menyesal, serta menderita akibat yang sangat tidak masuk akal.",
  ui_story_31210602_157_dialog_content = "Aku penasaran... Apa pendapatmu tentang orang-orang itu?",
  ui_story_31210602_158_option_content = "Mereka hanya sekumpulan makhluk menyedihkan, didominasi oleh keinginan dasar.",
  ui_story_31210602_159_option_content = "Orang-orang itu sangat menjijikkan! Ih!",
  ui_story_31210602_160_dialog_content = "Mereka membuat topeng kepura-puraan atas nama dewa palsu untuk menutupi keburukan dan keji mereka sendiri.",
  ui_story_31210602_161_dialog_content = "Agama seharusnya murni dan meningkatkan semangat, dengan cita-cita mulia dan harapan yang menginspirasi untuk masa depan, tetapi sering digunakan oleh orang jahat untuk meracuni dunia.",
  ui_story_31210602_162_dialog_content = "Hmm! Benar sekali!",
  ui_story_31210602_163_dialog_content = "Sejujurnya, saya tidak begitu mengerti semua ide besar itu. Saya sebenarnya masih sedikit khawatir tentang kamu dan foto-foto yang diambil oleh pria itu...",
  ui_story_31210602_164_dialog_content = "Mengapa kamu khawatir tentang aku? Aku tidak melakukan kesalahan apa pun.",
  ui_story_31210602_165_dialog_content = "Aku takkan pernah membiarkan hal seperti ini mengalahkanku. Tak ada yang salah dengan apa yang aku kenakan, dan aku merasa luar biasa.",
  ui_story_31210602_166_dialog_content = "Untuk para pelaku jahat yang tidak tahu malu itu, saya akan mengalahkan mereka dengan kehormatan dan integritas, setiap waktu!",
  ui_story_31210602_167_dialog_content = "Dan itu persis yang kamu lakukan!",
  ui_story_31210602_168_dialog_content = "Ngomong-ngomong, foto ini yang kamu berikan tadi... Kamu mau kembaliin?",
  ui_story_31210602_169_dialog_content = "Ini selfie saya pakai baju renang. Apakah kamu merasa kurang menarik?",
  ui_story_31210602_170_dialog_content = "Tentu saja tidak. Kamu terlihat sangat cantik dan percaya diri di foto ini.",
  ui_story_31210602_171_dialog_content = "Pikirkan itu sebagai hadiah dari seorang teman!",
  ui_story_31210602_172_dialog_content = "(Foto Paloma yang menghadap kamera dengan begitu berani ini sungguh menakjubkan... Ini sejuta kali lebih indah daripada foto yang diambil tanpa sepengetahuannya dari bayang-bayang...)",
  ui_story_31210602_173_dialog_content = "(Andai saja ada cara untuk menghentikan orang melakukan hal seperti ini... Maymungkin saya bisa membahas masalah ini dengan Paloma di masa depan...)"
}
return config
